def merge(intervals):
    # 核心思路：先按左端点排序，使可能重叠的区间必然相邻，再线性扫描合并。
    # 关键步骤：当前区间左端点不超过结果末尾区间的右端点时合并，并把右端点
    # 更新为两者较大值；否则作为新区间直接加入结果。
    # 复杂度：时间 O(n log n)（排序主导），空间 O(n)。
    intervals.sort()
    res = []
    for l, r in intervals:
        if res and l <= res[-1][1]:
            res[-1][1] = max(res[-1][1], r)
        else:
            res.append([l, r])
    return res

