def setZeroes(matrix):
    # 核心思路：用第一行和第一列充当标记数组，实现 O(1) 额外空间。
    # 关键步骤：先单独记录第一行、第一列本身是否含 0；再用第一行第一列的
    # 标记把内部元素置零；最后根据记录单独处理第一行第一列，避免标记被覆盖。
    # 复杂度：时间 O(mn)，空间 O(1)。
    m, n = len(matrix), len(matrix[0])
    first_row = any(v == 0 for v in matrix[0])
    first_col = any(matrix[i][0] == 0 for i in range(m))
    for i in range(1, m):
        for j in range(1, n):
            if matrix[i][j] == 0:
                matrix[i][0] = 0
                matrix[0][j] = 0
    for i in range(1, m):
        for j in range(1, n):
            if matrix[i][0] == 0 or matrix[0][j] == 0:
                matrix[i][j] = 0
    if first_row:
        for j in range(n):
            matrix[0][j] = 0
    if first_col:
        for i in range(m):
            matrix[i][0] = 0

